INSERT OR IGNORE INTO question_bank_versions SELECT 'pre-added-questions-1140',payload,revision,datetime('now') FROM question_bank WHERE id=1;
CREATE TABLE incoming_questions_v4 (id INTEGER PRIMARY KEY, category TEXT NOT NULL, question TEXT NOT NULL, data TEXT NOT NULL);
UPDATE question_bank SET payload=json_set(payload,'$.questions',json((SELECT json_group_array(json(value)) FROM (SELECT value FROM json_each(question_bank.payload,'$.questions') UNION ALL SELECT data AS value FROM incoming_questions_v4 n WHERE NOT EXISTS (SELECT 1 FROM json_each(question_bank.payload,'$.questions') e WHERE json_extract(e.value,'$.id')=n.id OR (json_extract(e.value,'$.category')=n.category AND json_extract(e.value,'$.question')=n.question)))))),revision=revision+1 WHERE id=1;
DROP TABLE incoming_questions_v4;
