INSERT INTO incoming_questions_v4 VALUES(947,'سياحة وسفر','كم يبلغ عدد عجائب الدنيا السبع الجديدة التي اختيرت في التصويت العالمي الشهير في لشبونة (إلى جانب هرم الجيزة كعضو شرفي)؟','{"id": 947, "categoryId": "c19", "category": "سياحة وسفر", "question": "كم يبلغ عدد عجائب الدنيا السبع الجديدة التي اختيرت في التصويت العالمي الشهير في لشبونة (إلى جانب هرم الجيزة كعضو شرفي)؟", "answer": "7 عجائب البتراء، تاج محل، سور الصين، الكولوسيوم، ماتشو بيتشو، تشيتشن إيتزا، وتمثال المسيح الفادي", "points": 600, "sourcePoints": 600, "sourceIndex": 946, "difficulty": "صعب", "options": ["6 عجائب حدائق بابل، منارة الإسكندرية، معبد أرتميس، الكولوسيوم، والبتراء", "5 عجائب برج إيفل، ساعة بيغ بن، الأوبرا بسيدني، الكرملين، وتاج محل", "7 عجائب البتراء، تاج محل، سور الصين، الكولوسيوم، ماتشو بيتشو، تشيتشن إيتزا، وتمثال المسيح الفادي", "8 عجائب معبد الكرنك، الحمراء، برج بيزا، سور الصين، الحجر، البتراء، وتاج محل"], "optionsSource": "provided-question-bank", "hint": "حرف الإجابة الأول: 7", "hintSource": "generated-letter-hint"}');
